import { cities } from "../cities.js";

<let/searchQuery="">

<input
  id="q"
  type="text"
  placeholder="Search cities..."
  on-input=(event) => {
    searchQuery = event.target.value;
  }
/>

<ul id="results">
  <for|city| of=cities.filter(c => 
    !searchQuery || c.toLowerCase().includes(searchQuery.toLowerCase())
  )>
    <li>${city}</li>
  </for>
</ul>

<div id="count">${cities.filter(c => 
  !searchQuery || c.toLowerCase().includes(searchQuery.toLowerCase())
).length} matches</div>

