let todos = [];
let nextId = 0;

<div>
  <div>
    <input id="new-todo" type="text" />
    <button
      id="add"
      on-click=() => {
        const input = document.getElementById('new-todo');
        const text = input.value.trim();
        if (text) {
          todos.push({
            id: nextId++,
            text: text,
            done: false
          });
          input.value = '';
        }
      }
    >
      Add
    </button>
  </div>

  <if (todos.length === 0)>
    <div id="empty">No todos yet</div>
  </if>
  <else>
    <ul id="list">
      <for|todo| of todos>
        <li>
          <input
            type="checkbox"
            checked=todo.done
            on-change=() => {
              todo.done = !todo.done;
            }
          />
          ${todo.text}
        </li>
      </for>
    </ul>
  </else>

  <div id="remaining">
    ${todos.filter(t => !t.done).length} left
  </div>
</div>

$ {
