}

<div>
  <div role="tablist">
    <for|tab, i| of=input.tab>
      <button
        aria-selected=(i === activeIndex ? "true" : undefined)
        on-click() {
          activeIndex = i;
        }
      >
        ${tab.label}
      </button>
    </for>
  </div>

  <div id="panel">
    ${input.tab[activeIndex]?.renderBody()}
  </div>

  <div style="display: none">
    <@slot name="tab" label />
  </div>
</div>

